<?php
namespace App\Http\Middleware; use App\Services\Dapcode\LicenseGuard; use Closure; use Illuminate\Http\Request; class DapcodeLicenseMiddleware { public function handle(Request $request, Closure $next, ? string $module = null) { if (LicenseGuard::isExcludedRequest($request)) { return $next($request); } $targetModule = $module ?? $request->route('module') ?? $request->segment(1); LicenseGuard::assertModuleAllowed($targetModule); return $next($request); } }